import{_ as t,o as d,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/FREQUENCIES.md","filePath":"manual-en/FREQUENCIES.md","lastUpdated":1785684581000}'),o={name:"manual-en/FREQUENCIES.md"};function n(r,e,i,c,l,u){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h3 id="_15-2-frequencies" tabindex="-1">15.2 FREQUENCIES <a class="header-anchor" href="#_15-2-frequencies" aria-label="Permalink to &quot;15.2 FREQUENCIES&quot;">​</a></h3><pre><code>FREQUENCIES
        /VARIABLES=var_list
        /FORMAT={TABLE,NOTABLE,LIMIT(limit)}
                {AVALUE,DVALUE,AFREQ,DFREQ}
        /MISSING={EXCLUDE,INCLUDE}
        /STATISTICS={DEFAULT,MEAN,SEMEAN,MEDIAN,MODE,STDDEV,VARIANCE,
                     KURTOSIS,SKEWNESS,RANGE,MINIMUM,MAXIMUM,SUM,
                     SESKEWNESS,SEKURTOSIS,ALL,NONE}
        /NTILES=ntiles
        /PERCENTILES=percent…
        /HISTOGRAM=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                   [{FREQ[(y_max)],PERCENT[(y_max)]}] [{NONORMAL,NORMAL}]
        /PIECHART=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                  [{FREQ,PERCENT}] [{NOMISSING,MISSING}]
        /BARCHART=[MINIMUM(x_min)] [MAXIMUM(x_max)]
                  [{FREQ,PERCENT}]
        /ORDER={ANALYSIS,VARIABLE}


(These options are not currently implemented.)
        /HBAR=…
        /GROUPED=…
</code></pre><p>The <code>FREQUENCIES</code> procedure outputs frequency tables for specified variables. <code>FREQUENCIES</code> can also calculate and display descriptive statistics (including median and mode) and percentiles, and various graphical representations of the frequency distribution.</p><p>The <code>VARIABLES</code> subcommand is the only required subcommand. Specify the variables to be analyzed.</p><p>The <code>FORMAT</code> subcommand controls the output format. It has several possible settings:</p><ul><li>\`\` <code>TABLE</code>, the default, causes a frequency table to be output for every variable specified. <code>NOTABLE</code> prevents them from being output. <code>LIMIT</code> with a numeric argument causes them to be output except when there are more than the specified number of values in the table.</li><li>\`\` Normally frequency tables are sorted in ascending order by value. This is <code>AVALUE</code>. <code>DVALUE</code> tables are sorted in descending order by value. <code>AFREQ</code> and <code>DFREQ</code> tables are sorted in ascending and descending order, respectively, by frequency count.</li></ul><p>The <code>MISSING</code> subcommand controls the handling of user-missing values. When <code>EXCLUDE</code>, the default, is set, user-missing values are not included in frequency tables or statistics. When <code>INCLUDE</code> is set, user-missing are included. System-missing values are never included in statistics, but are listed in frequency tables.</p><p>The available <code>STATISTICS</code> are the same as available in <code>DESCRIPTIVES</code> (see <a href="./DESCRIPTIVES">DESCRIPTIVES</a>), with the addition of <code>MEDIAN</code>, the data’s median value, and MODE, the mode. (If there are multiple modes, the smallest value is reported.) By default, the mean, standard deviation of the mean, minimum, and maximum are reported for each variable.</p><p><code>PERCENTILES</code> causes the specified percentiles to be reported. The percentiles should be presented at a list of numbers between 0 and 100 inclusive. The <code>NTILES</code> subcommand causes the percentiles to be reported at the boundaries of the data set divided into the specified number of ranges. For instance, <code>/NTILES=4</code> would cause quartiles to be reported.</p><p>The <code>HISTOGRAM</code> subcommand causes the output to include a histogram for each specified numeric variable. The X axis by default ranges from the minimum to the maximum value observed in the data, but the <code>MINIMUM</code> and <code>MAXIMUM</code> keywords can set an explicit range. 6 Histograms are not created for string variables.</p><p>Specify <code>NORMAL</code> to superimpose a normal curve on the histogram.</p><p>The <code>PIECHART</code> subcommand adds a pie chart for each variable to the data. Each slice represents one value, with the size of the slice proportional to the value’s frequency. By default, all non-missing values are given slices. The <code>MINIMUM</code> and <code>MAXIMUM</code> keywords can be used to limit the displayed slices to a given range of values. The keyword <code>NOMISSING</code> causes missing values to be omitted from the piechart. This is the default. If instead, <code>MISSING</code> is specified, then the pie chart includes a single slice representing all system missing and user-missing cases.</p><p>The <code>BARCHART</code> subcommand produces a bar chart for each variable. The <code>MINIMUM</code> and <code>MAXIMUM</code> keywords can be used to omit categories whose counts which lie outside the specified limits. The <code>FREQ</code> option (default) causes the ordinate to display the frequency of each category, whereas the <code>PERCENT</code> option displays relative percentages.</p><p>The <code>FREQ</code> and <code>PERCENT</code> options on <code>HISTOGRAM</code> and <code>PIECHART</code> are accepted but not currently honoured.</p><p>The <code>ORDER</code> subcommand is accepted but ignored.</p><h4 id="_15-2-1-frequencies-example" tabindex="-1">15.2.1 Frequencies Example <a class="header-anchor" href="#_15-2-1-frequencies-example" aria-label="Permalink to &quot;15.2.1 Frequencies Example&quot;">​</a></h4><p>Example 15.2 runs a frequency analysis on the <strong>sex</strong> and <strong>occupation</strong> variables from the personnel.sav file. This is useful to get a general idea of the way in which these nominal variables are distributed.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;personnel.sav&#39;.  frequencies /variables = sex occupation             /statistics = none.</span></span></code></pre></div><p><strong>Example 15.2:</strong> Running frequencies on the <strong>sex</strong> and <strong>occupation</strong> variables</p><p>If you are using the graphic user interface, the dialog box is set up such that by default, several statistics are calculated. Some are not particularly useful for categorical variables, so you may want to disable those.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.2:</strong> The frequencies dialog box with the <strong>sex</strong> and <strong>occupation</strong> variables selected</p><p>From Result 15.2 it is evident that there are 33 males, 21 females and 2 persons for whom their sex has not been entered.</p><p>One can also see how many of each occupation there are in the data. When dealing with string variables used as nominal values, running a frequency analysis is useful to detect data input entries. Notice that one <strong>occupation</strong> value has been mistyped as “Scrientist”. This entry should be corrected, or marked as missing before using the data.</p><table tabindex="0"><thead><tr><th></th><th></th><th>Frequency</th><th>Percent</th><th>Valid Percent</th><th>Cumulative Percent</th></tr></thead><tbody><tr><td>Valid</td><td>Male</td><td>33</td><td>58.9%</td><td>61.1%</td><td>61.1%</td></tr><tr><td>Female</td><td>21</td><td>37.5%</td><td>38.9%</td><td>100.0%</td><td></td></tr><tr><td>Missing</td><td>.</td><td>2</td><td>3.6%</td><td></td><td></td></tr><tr><td>Total</td><td>56</td><td>100.0%</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Frequency</td><td>Percent</td><td>Valid Percent</td><td>Cumulative Percent</td></tr><tr><td>Valid</td><td>Artist</td><td>8</td><td>14.3%</td><td>14.3%</td><td>14.3%</td></tr><tr><td>Baker</td><td>2</td><td>3.6%</td><td>3.6%</td><td>17.9%</td><td></td></tr><tr><td>Barrister</td><td>1</td><td>1.8%</td><td>1.8%</td><td>19.6%</td><td></td></tr><tr><td>Carpenter</td><td>4</td><td>7.1%</td><td>7.1%</td><td>26.8%</td><td></td></tr><tr><td>Cleaner</td><td>4</td><td>7.1%</td><td>7.1%</td><td>33.9%</td><td></td></tr><tr><td>Cook</td><td>7</td><td>12.5%</td><td>12.5%</td><td>46.4%</td><td></td></tr><tr><td>Manager</td><td>8</td><td>14.3%</td><td>14.3%</td><td>60.7%</td><td></td></tr><tr><td>Mathematician</td><td>4</td><td>7.1%</td><td>7.1%</td><td>67.9%</td><td></td></tr><tr><td>Painter</td><td>2</td><td>3.6%</td><td>3.6%</td><td>71.4%</td><td></td></tr><tr><td>Payload Specialist</td><td>1</td><td>1.8%</td><td>1.8%</td><td>73.2%</td><td></td></tr><tr><td>Plumber</td><td>5</td><td>8.9%</td><td>8.9%</td><td>82.1%</td><td></td></tr><tr><td>Scientist</td><td>7</td><td>12.5%</td><td>12.5%</td><td>94.6%</td><td></td></tr><tr><td>Scrientist</td><td>1</td><td>1.8%</td><td>1.8%</td><td>96.4%</td><td></td></tr><tr><td>Tailor</td><td>2</td><td>3.6%</td><td>3.6%</td><td>100.0%</td><td></td></tr><tr><td>Total</td><td>56</td><td>100.0%</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Result 15.2:</strong> The relative frequencies of <strong>sex</strong> and <strong>occupation</strong></p><h4 id="footnotes" tabindex="-1">Footnotes <a class="header-anchor" href="#footnotes" aria-label="Permalink to &quot;Footnotes&quot;">​</a></h4><h5 id="_6" tabindex="-1">(6) <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;(6)&quot;">​</a></h5><p>The number of bins is chosen according to the Freedman-Diaconis rule: <em>2 \\times IQR(x)n^{-1/3}</em> , where <em>IQR(x)</em> is the interquartile range of <em>x</em> and <em>n</em> is the number of samples. Note that <code>EXAMINE</code> uses a different algorithm to determine bin sizes.</p>`,29)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
